+        columns.push(Arc::new(self.seqstart.finish()));
+        columns.push(Arc::new(self.seqincrement.finish()));
+        columns.push(Arc::new(self.seqmax.finish()));
+        columns.push(Arc::new(self.seqmin.finish()));
