+  // eslint-disable-next-line @typescript-eslint/no-use-before-define
+  @OneToMany(() => Book, book => book.author)
+  books = new Collection<Book>(this);
+
+  constructor(name: string) {
+    this.name = name;
+  }
+
+}
+
+@Entity()
+export class Book {
+
+  @PrimaryKey()
+  id!: number;
+
+  @ManyToOne(() => Author)
+  author!: Author;
+
+  @Property({ length: 42 })
+  name!: string;
+
+  constructor(name: string) {
+    this.name = name;
+  }
+
